ProjectAutosave::~ProjectAutosave()
{
    m_subscription.reset();
    if (m_worker.valid())
        m_worker.wait();
}

std::string ProjectAutosave::project_name() const
{
    return m_project_name.empty() ? std::string(m_plater.get_project_name().ToUTF8()) : m_project_name;
}

void ProjectAutosave::fail(const std::string& message)
{
    BOOST_LOG_TRIVIAL(error) << "Local project save failed: " << message;
    m_error = message;
                                                SaveStrategy::Backup | SaveStrategy::Silence);
        if (result < 0)
            throw std::runtime_error("OrcaSlicer could not capture project metadata");
        protect_saved_settings(metadata);
        const wxString source = m_plater.get_project_filename(".3mf");
        auto frozen = m_store->freeze(m_plater.model(), id, ++m_revision, m_persistence.document().dump(),
                                      source.ToUTF8().data(), m_persistence.timestamp());
        const auto& changes = m_persistence.document().changes();
        if (!changes.empty())
            frozen.version.change_seq = changes.back().seq;
        const auto semantic_revision = m_persistence.document().doc_revision();
        m_committed_semantic_revision = semantic_revision;
        if (m_seen_semantic_revision == semantic_revision)
            m_first_semantic_edit.reset();
        const std::string plater_name(m_plater.get_project_name().ToUTF8());
        const std::string untitled(_L("Untitled").ToUTF8());
        frozen.version.project_name = m_project_name.empty() ? plater_name : m_project_name;
        // A project with no name yet takes its first object's. One the store
        // already named keeps it: a reopened project's Orca name reads
        // Untitled, and its next version must not rename it.
        if ((m_project_name.empty() || m_project_name == untitled) && (plater_name.empty() || plater_name == untitled) &&
            !m_plater.model().objects.empty())
            frozen.version.project_name = std::filesystem::u8path(m_plater.model().objects.front()->name).stem().u8string();
        m_project_name = frozen.version.project_name;
        // A project adopted before Orca named its file gets it with its first
        // version.
        if (m_opened_from.empty() && m_store->head_id().empty() && !source.empty()) {
            m_opened_from   = source.ToUTF8().data();
            m_opened_digest = file_digest(std::filesystem::u8path(m_opened_from));
        }
        frozen.version.opened_from = m_opened_from;
        home_x += m_left_pane_toggle->GetBestSize().x + gap;
    }
    place(m_home_button,home_x);
    const int left = home_x+m_home_button->GetBestSize().x+gap;
    const int available = std::max(0,right-gap-left);
    const int width = std::min(m_chip->GetBestSize().x,available);
    const wxSize chip = m_chip->GetBestSize();
    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
}

wxString StatusRow::project_name() const
{
    const wxString name = m_autosave != nullptr ? wxString::FromUTF8(m_autosave->project_name())
                                                : m_plater.get_project_name();
    return name.empty() ? _L("Untitled") : name;
}

wxString StatusRow::save_state() const
{
    if (m_autosave == nullptr)
        return m_plater.is_project_dirty() ? _L("Unsaved changes") : wxString();
    switch (m_autosave->state()) {
    case Workspace::ProjectAutosave::State::Saving: return _L("Saving…");
    case Workspace::ProjectAutosave::State::Saved: return _L("Saved");
    case Workspace::ProjectAutosave::State::Failed: return _L("Couldn't save");
    }
    throw std::logic_error("Unknown autosave state");
}

wxString StatusRow::project_summary() const
{
    const wxString state = save_state();
    return state.empty() ? project_name() : project_name() + em_dash() + state;
}

void StatusRow::request_home()
{
    m_tabpanel.SetSelection(MainFrame::tpHome);
}

// The chip renders Orca's own selection and nothing else: the printer, and
// one dot per project slot. Nothing here writes; a change goes through the
// filament menu and SetupCommands.
void StatusRow::refresh_chip()
{
    const auto printer = SetupCommands::current_printer();
    // One nozzle size is said once; a printer with several says each.
    std::vector<double> sizes = printer.nozzles;
    std::sort(sizes.begin(), sizes.end());
    sizes.erase(std::unique(sizes.begin(), sizes.end()), sizes.end());
    wxString nozzle;
    for (double size : sizes)
        nozzle += (nozzle.empty() ? wxString() : wxString(" / ")) + wxString::Format("%g", size);
    wxString printer_tooltip = printer.nickname;
    if (!nozzle.empty())
        printer_tooltip += middle_dot() + nozzle + " mm " + (sizes.size() > 1 ? _L("nozzles") : _L("nozzle"));
    if (printer.from_file) {
        const wxString project = m_plater.get_project_name();
        printer_tooltip += middle_dot() +
                           wxString::Format(_L("from %s, not one of the printers you set up"),
                                            project.empty() ? _L("the file") : project + ".3mf");
    }
    m_chip->set_printer(printer.nickname, printer.valid ? nozzle : wxString{}, printer_tooltip, printer.from_file);

    const auto slots = SetupCommands::filament_slots();
    std::vector<ChipSlot> chip_slots;

